#!/usr/bin/env python3
"""Static scanner: capture -> reallocating pull -> stale-use, same function scope.
Branch rx-pull-stale-hdr for snapshot s04 (linux tree)."""
import os, re, sys, json

SNAP = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/10_cluster/C6/public/snapshots/s04"

PULL_CALLS = re.compile(
    r'\b(pskb_may_pull|__pskb_may_pull|pskb_pull|__pskb_pull|__pskb_pull_tail|'
    r'skb_linearize|__skb_linearize|pskb_expand_head|skb_cow|skb_cow_head|skb_unclone)\s*\(')

# var = <expr capturing a pointer into an skb head>
CAPTURE_RE = re.compile(
    r'(?<![\w\.\->])([A-Za-z_]\w*)\s*=\s*(?:\([A-Za-z_][\w\s\*]*\)\s*)?'
    r'(skb_header_pointer\s*\(|skb->data\b|skb_network_header\s*\(|skb_transport_header\s*\(|'
    r'skb_mac_header\s*\(|ipv6_hdr\s*\(|ip_hdr\s*\(|tcp_hdr\s*\(|udp_hdr\s*\(|icmp6_hdr\s*\(|'
    r'icmp_hdr\s*\(|eth_hdr\s*\(|mpls_hdr\s*\(|dccp_hdr\s*\(|sctp_hdr\s*\(|gre_hdr\s*\(|'
    r'ipip_hdr\s*\(|ipv6_find_hdr\s*\(|skb_gro_header)')

FUNC_START = re.compile(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\([^;]*$')

def strip_code(line):
    # remove comments and string literals (rough)
    line = re.sub(r'/\*.*?\*/', '', line)
    line = re.sub(r'//[^\n]*', '', line)
    line = re.sub(r'"(\\.|[^"\\])*"', '""', line)
    return line

def functions(lines):
    """yield (start_line_idx0, name, [lines with absolute numbers])"""
    i = 0
    n = len(lines)
    while i < n:
        raw = lines[i]
        code = strip_code(raw)
        if FUNC_START.match(code) and '{' not in code:
            # find opening brace within next few lines
            j = i
            sig = code
            while j < n and j < i + 8:
                if '{' in strip_code(lines[j]):
                    break
                if ';' in strip_code(lines[j]):  # prototype
                    j = -1
                    break
                sig += ' ' + strip_code(lines[j])
                j += 1
            else:
                j = -1
            if j != -1 and j < n and '{' in strip_code(lines[j]):
                # collect function body by brace matching
                depth = 0
                body = []
                k = j
                started = False
                while k < n:
                    c = strip_code(lines[k])
                    for ch in c:
                        if ch == '{':
                            depth += 1
                            started = True
                        elif ch == '}':
                            depth -= 1
                    body.append((k + 1, c))  # 1-based line number
                    if started and depth == 0:
                        break
                    k += 1
                m = re.search(r'([A-Za-z_]\w*)\s*\(', sig)
                fname = m.group(1) if m else '?'
                yield (j + 1, fname, body)
                i = k + 1
                continue
        i += 1

def analyze(path):
    results = []
    try:
        with open(path, 'r', errors='replace') as f:
            lines = f.read().split('\n')
    except Exception:
        return results
    for fstart, fname, body in functions(lines):
        # gather events
        events = []  # (line, kind, var)
        for ln, code in body:
            if not code.strip():
                continue
            for m in CAPTURE_RE.finditer(code):
                var = m.group(1)
                if var in ('if', 'for', 'while', 'switch', 'return', 'else', 'goto', 'sizeof', 'typeof'):
                    continue
                events.append((ln, 'capture', var))
            for m in PULL_CALLS.finditer(code):
                events.append((ln, 'pull', m.group(1)))
            # reassignments
            for m in re.finditer(r'(?<![\w\.\->])([A-Za-z_]\w*)\s*=\s*[^=]', code):
                var = m.group(1)
                events.append((ln, 'assign', var))
        if not events:
            continue
        # for each capture var, find pulls after capture, and uses after pull without reassign
        capture_vars = {}
        for ln, kind, var in events:
            if kind == 'capture':
                capture_vars.setdefault(var, ln)
        for var, capline in capture_vars.items():
            pulls = [ln for ln, kind, v in events if kind == 'pull' and ln >= capline]
            if not pulls:
                continue
            firstpull = min(pulls)
            # uses after first pull
            uses = []
            stale = False
            reassigned_at = None
            for ln, code in body:
                if ln <= firstpull:
                    continue
                # reassignment of var ends staleness
                if re.search(r'(?<![\w\.\->])' + re.escape(var) + r'\s*=\s*[^=]', code):
                    reassigned_at = ln
                    break
            for ln, code in body:
                if ln <= firstpull:
                    continue
                if reassigned_at is not None and ln >= reassigned_at:
                    break
                if re.search(r'(?<![\w\.\->])' + re.escape(var) + r'\s*(->|\[|\)|\.|\+\+|--|\-|\+|\s*\*)', code):
                    uses.append(ln)
                elif re.search(r'->\s*' + re.escape(var) + r'\b', code):
                    pass  # field named like var, skip noise
            if uses:
                results.append({
                    'file': path, 'func': fname, 'func_start': fstart,
                    'var': var, 'capture_line': capline, 'pull_line': firstpull,
                    'use_lines': uses[:8],
                })
    return results

def main():
    roots = [os.path.join(SNAP, 'net'), os.path.join(SNAP, 'drivers')]
    all_res = []
    for root in roots:
        for dirpath, dirnames, filenames in os.walk(root):
            for fn in filenames:
                if not fn.endswith('.c'):
                    continue
                all_res.extend(analyze(os.path.join(dirpath, fn)))
    # dedupe by file/func/var/pull
    seen = set()
    out = []
    for r in all_res:
        key = (r['file'], r['func'], r['var'], r['pull_line'])
        if key in seen:
            continue
        seen.add(key)
        out.append(r)
    outpath = os.path.join(os.environ.get('TMPDIR', '/tmp'), 'i012', 'scan_results.json')
    with open(outpath, 'w') as f:
        json.dump(out, f, indent=1)
    print(f"total candidate chains: {len(out)}")
    for r in out:
        rel = os.path.relpath(r['file'], SNAP)
        print(f"{rel}:{r['func']}() var={r['var']} cap={r['capture_line']} pull={r['pull_line']} uses={r['use_lines']}")

if __name__ == '__main__':
    main()
